33	
34	#[ORM\Entity]
35	#[ORM\Table(name: 'orders')]
36	final class Order extends AggregateRoot
37	{
38	    /** @var Collection<int, OrderItem> */
39	    #[ORM\OneToMany(targetEntity: OrderItem::class, mappedBy: 'order', cascade: ['persist'], orphanRemoval: true)]
40	    private Collection $lines;
41	
42	    /**
43	     * Položky jen ke čtení: vrací se kopie, přidává se přes addItem().
44	     *
45	     * @var list<OrderItem>
46	     */
47	    public array $items {
48	        get => array_values($this->lines->toArray());
49	    }
50	
51	    // Asymetrická viditelnost: přečte kdokoli, zapíše jen kód uvnitř třídy.
52	    #[ORM\Column(enumType: OrderStatus::class)]
53	    public private(set) OrderStatus $status;
54	
55	    #[ORM\Column(nullable: true)]
56	    public private(set) ?\DateTimeImmutable $placedAt = null;
57	
58	    // Důvod storna.
59	    #[ORM\Column(type: 'text', nullable: true)]
60	    public private(set) ?string $cancellationNote = null;
61	
62	    // Sleva na celou objednávku. Kniha ji nemá, kurz ano (viz README).
63	    #[ORM\Embedded(class: Money::class, columnPrefix: 'discount_')]
64	    public private(set) Money $discount;
65	
66	    // Částka, kterou obchod po stornu vrátí zákazníkovi ručně (platební bránu nemáme).
67	    #[ORM\Column(options: ['default' => 0])]
68	    private int $refundDueInCents = 0;
69	
70	    private function __construct(
71	        #[ORM\Id]
72	        #[ORM\Column(type: 'order_id')]
73	        public readonly OrderId $id,
74	        #[ORM\Column(type: 'customer_id')]
75	        public readonly CustomerId $customerId,
76	        #[ORM\Column(enumType: Currency::class)]
77	        public readonly Currency $currency,
78	    ) {
79	        $this->status = OrderStatus::Draft;
80	        $this->lines = new ArrayCollection();
81	        $this->discount = Money::zero($currency);
82	    }
83	
84	    public static function place(OrderId $id, CustomerId $customerId, Currency $currency = Currency::CZK): self
85	    {
86	        $order = new self($id, $customerId, $currency);
87	        $order->record(new OrderPlaced($id, $customerId, new \DateTimeImmutable()));
88	
89	        return $order;
90	    }
91	
92	    public function addItem(ProductId $productId, int $quantity, Money $unitPrice): void
93	    {
94	        if ($this->status !== OrderStatus::Draft) {
95	            throw InvalidOrderStateTransitionException::notAllowedInState('addItem', $this->status->value);
96	        }
97	
98	        $this->assertSameCurrency($unitPrice);
99	
100	        // Jedna položka na produkt: množství se sčítá, položka se neduplikuje.
101	        foreach ($this->lines as $existing) {
102	            if ($existing->productId->equals($productId)) {
103	                $existing->increaseQuantity($quantity);
104	                $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
105	
106	                return;
107	            }
108	        }
109	
110	        $this->lines->add(new OrderItem($this, $productId, $quantity, $unitPrice));
111	        $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
112	    }
113	
114	    public function changeItemQuantity(ProductId $productId, int $quantity): void
115	    {
116	        if ($this->status !== OrderStatus::Draft) {
117	            throw InvalidOrderStateTransitionException::notAllowedInState('changeItemQuantity', $this->status->value);
118	        }
119	
120	        if ($quantity < 1) {
121	            throw InvalidQuantityException::mustBePositive($quantity);
122	        }
123	
124	        $this->itemFor($productId)->changeQuantity($quantity);
125	        $this->record(new OrderItemQuantityChanged($this->id, $productId, $quantity, new \DateTimeImmutable()));
126	    }
127	
128	    public function removeItem(ProductId $productId): void
129	    {
130	        if ($this->status !== OrderStatus::Draft) {
131	            throw InvalidOrderStateTransitionException::notAllowedInState('removeItem', $this->status->value);
132	        }
133	
134	        $item = $this->itemFor($productId);
135	        if ($this->lines->count() === 1) {
136	            throw LastItemCannotBeRemovedException::forProduct($productId);
137	        }
138	
139	        // Sleva nesmí po odebrání přesáhnout nový součet položek.
140	        $newTotal = $this->totalAmount()->subtract($item->subtotal());
141	        if ($this->discount->amountInCents > $newTotal->amountInCents) {
142	            throw DiscountExceedsItemsTotalException::forItemsTotal($this->discount, $newTotal);
143	        }
144	
145	        $this->lines->removeElement($item);
146	        $this->record(new OrderItemRemoved($this->id, $productId, new \DateTimeImmutable()));
147	    }
148	
149	    public function applyDiscount(Money $discount): void
150	    {
151	        if ($this->status !== OrderStatus::Draft) {
152	            throw InvalidOrderStateTransitionException::notAllowedInState('applyDiscount', $this->status->value);
153	        }
154	
155	        $this->assertSameCurrency($discount);
156	
157	        $total = $this->totalAmount();
158	        if ($discount->amountInCents > $total->amountInCents) {
159	            throw DiscountExceedsItemsTotalException::forItemsTotal($discount, $total);
160	        }
161	
162	        $this->discount = $discount;
163	    }
164	
165	    public function confirm(?\DateTimeImmutable $at = null): void
166	    {
167	        if (!$this->status->canTransitionTo(OrderStatus::Confirmed)) {
168	            throw InvalidOrderStateTransitionException::cannotTransition(
169	                $this->status->value,
170	                OrderStatus::Confirmed->value,
171	            );
172	        }
173	
174	        if ($this->lines->isEmpty()) {
175	            throw EmptyOrderException::cannotConfirm();
176	        }
177	
178	        $this->status = OrderStatus::Confirmed;
179	        $this->placedAt = $at ?? new \DateTimeImmutable();
180	        $this->record(new OrderConfirmed($this->id, $this->customerId, $this->placedAt));
181	    }
182	
183	    public function markPaid(): void
184	    {
185	        // Opakované doručení příkazu o platbě není chyba volajícího.
186	        if ($this->status === OrderStatus::Paid) {
187	            return;
188	        }
189	
190	        if (!$this->status->canTransitionTo(OrderStatus::Paid)) {
191	            throw InvalidOrderStateTransitionException::cannotTransition(
192	                $this->status->value,
193	                OrderStatus::Paid->value,
194	            );
195	        }
196	
197	        $this->status = OrderStatus::Paid;
198	        $this->record(new OrderPaid($this->id, new \DateTimeImmutable()));
199	    }
200	
201	    public function ship(): void
202	    {
203	        if ($this->status === OrderStatus::Shipped) {
204	            return;
205	        }
206	
207	        if (!$this->status->canTransitionTo(OrderStatus::Shipped)) {
208	            throw InvalidOrderStateTransitionException::cannotTransition(
209	                $this->status->value,
210	                OrderStatus::Shipped->value,
211	            );
212	        }
213	
214	        $this->status = OrderStatus::Shipped;
215	        $this->record(new OrderShipped($this->id, new \DateTimeImmutable()));
216	    }
217	
218	    public function deliver(): void
219	    {
220	        if (!$this->status->canTransitionTo(OrderStatus::Delivered)) {
221	            throw InvalidOrderStateTransitionException::cannotTransition(
222	                $this->status->value,
223	                OrderStatus::Delivered->value,
224	            );
225	        }
226	
227	        $this->status = OrderStatus::Delivered;
228	        $this->record(new OrderDelivered($this->id, new \DateTimeImmutable()));
229	    }
230	
231	    // Čas přichází zvenku, aby šel v testech zadat.
232	    public function cancel(string $reason, \DateTimeImmutable $when): void
233	    {
234	        // Opakované storno není chyba volajícího, jen už není co dělat.
235	        if ($this->status === OrderStatus::Cancelled) {
236	            return;
237	        }
238	
239	        // Storno je hrana grafu jako každá jiná: odeslanou ani doručenou
240	        // objednávku zpátky nevrátí.
241	        if (!$this->status->canTransitionTo(OrderStatus::Cancelled)) {
242	            throw InvalidOrderStateTransitionException::cannotTransition(
243	                $this->status->value,
244	                OrderStatus::Cancelled->value,
245	            );
246	        }
247	
248	        // Zaplacenou objednávku vrací obchod zákazníkovi celou.
249	        if ($this->status === OrderStatus::Paid) {
250	            $this->refundDueInCents = $this->paidAmount()->amountInCents;
251	        }
252	
253	        $this->status = OrderStatus::Cancelled;
254	        $this->cancellationNote = $reason === '' ? null : $reason;
255	        $this->record(new OrderCancelled($this->id, $this->customerId, $reason, $when));
256	    }
257	
258	    public function isOwnedBy(CustomerId $customerId): bool
259	    {
260	        return $this->customerId->equals($customerId);
261	    }
262	
263	    /** Součet položek před slevou. */
264	    public function totalAmount(): Money
265	    {
266	        $total = Money::zero($this->currency);
267	        foreach ($this->lines as $item) {
268	            $total = $total->add($item->subtotal());
269	        }
270	
271	        return $total;
272	    }
273	
274	    /** Částka, kterou zákazník platí: součet položek po slevě. */
275	    public function paidAmount(): Money
276	    {
277	        return $this->totalAmount()
278	            ->subtract($this->discount);
279	    }
280	
281	    /** Částka k vrácení zákazníkovi po stornu zaplacené objednávky, jinak nula. */
282	    public function refundDue(): Money
283	    {
284	        return new Money($this->refundDueInCents, $this->currency);
285	    }
286	
287	    private function itemFor(ProductId $productId): OrderItem
288	    {
289	        foreach ($this->lines as $item) {
290	            if ($item->productId->equals($productId)) {
291	                return $item;
292	            }
293	        }
294	
295	        throw OrderItemNotFoundException::forProduct($productId);
296	    }
297	
298	    private function assertSameCurrency(Money $amount): void
299	    {
300	        if ($amount->currency !== $this->currency) {
301	            throw CurrencyMismatchException::forOrder($this->currency, $amount->currency);
302	        }
303	    }
304	}
